def solve(xs: list[int]) -> int:
    """Return the largest (max - min) over all contiguous windows of length 3.

    If the list has fewer than 3 elements, return 0.
    """
    if len(xs) < 3:
        return 0
    best = 0
    for i in range(len(xs) - 2):
        a, b, c = xs[i], xs[i + 1], xs[i + 2]
        diff = max(a, b, c) - min(a, b, c)
        if diff > best:
            best = diff
    return best

def solve(xs: list[int]) -> int:
    s = sum(xs)
    if len(set(xs)) == 1:
        return s
    has_odd = any(x % 2 != 0 for x in xs)
    has_even = any(x % 2 == 0 for x in xs)
    if has_odd:
        if s % 2 != 0:
            s += 1
    elif has_even:
        if s % 2 == 0:
            s += 1
    return s
